197|static void remove_trailing_blank_lines(cmark_strbuf *ln) {
198|  bufsize_t i;
199|  unsigned char c;
200|
201|  for (i = ln->size - 1; i >= 0; --i) {
202|    c = ln->ptr[i];
203|
204|    if (c != ' ' && c != '\t' && !S_is_line_end_char(c))
205|      break;
206|  }
207|
208|  if (i < 0) {
209|    cmark_strbuf_clear(ln);
210|    return;
211|  }
212|
213|  for (; i < ln->size; ++i) {
214|    c = ln->ptr[i];
215|
216|    if (!S_is_line_end_char(c))
217|      continue;
218|
219|    cmark_strbuf_truncate(ln, i);
220|    break;
221|  }
