798|static bool parse_node_item_prefix(cmark_parser *parser, cmark_chunk *input,
799|                                   cmark_node *container) {
800|  bool res = false;
801|
802|  if (parser->indent >=
803|      container->as.list.marker_offset + container->as.list.padding) {
804|    S_advance_offset(parser, input, container->as.list.marker_offset +
805|                                        container->as.list.padding,
806|                     true);
807|    res = true;
808|  } else if (parser->blank && container->first_child != NULL) {
809|    // if container->first_child is NULL, then the opening line
810|    // of the list item was blank after the list marker; in this
811|    // case, we are done with the list item.
812|    S_advance_offset(parser, input, parser->first_nonspace - parser->offset,
813|                     false);
814|    res = true;
815|  }
816|  return res;
